            <= 1 => GameVersion.MP4 | GameVersion.TM2020,
            <= 2 => GameVersion.TM2020,
            _ => GameVersion.MP4 | GameVersion.TM2020,
        };
        public int Version { get; set; }
        public int? U01;
        public string? U02;
        public string? U03;
        public string? U04;
        public bool? U05;
        public bool? U06;

        public Chunk03090012() : this(GameVersion.Unspecified)
        {
        }

        public Chunk03090012(GameVersion gameVersion)
        {
            if (gameVersion == GameVersion.MP4)
            {
                Version = 1;
            }
            else if (gameVersion == GameVersion.TM2020)
            {
                Version = 2;
            }
        }

        internal override void DeepCloneFields(Chunk clone, DeepCloneContext context)
        {
            base.DeepCloneFields(clone, context);
            ((Chunk03090012)clone).Version = context.Clone(this.Version)!;
            ((Chunk03090012)clone).U01 = context.Clone(this.U01)!;
            ((Chunk03090012)clone).U02 = context.Clone(this.U02)!;
            ((Chunk03090012)clone).U03 = context.Clone(this.U03)!;
            ((Chunk03090012)clone).U04 = context.Clone(this.U04)!;
            ((Chunk03090012)clone).U05 = context.Clone(this.U05)!;
            ((Chunk03090012)clone).U06 = context.Clone(this.U06)!;
        }

        public override void ReadWrite(CGameCtnCampaign n, GbxReaderWriter rw)
        {
            rw.VersionInt32(this);
            if (Version > 2)
            {
                throw new global::GBX.NET.Exceptions.ChunkVersionNotSupportedException(Version);
            }

            if (Version <= 1)
            {
                rw.String(ref n.scoreContext);
            }

            if (Version >= 2)
            {
                rw.Int32(ref U01);
                rw.String(ref U02);
                rw.String(ref U03);
                rw.String(ref U04);
            }

            rw.Boolean(ref n.officialRecordEnabled);

            if (Version == 0)
            {
                rw.Boolean(ref U05);
                rw.Boolean(ref U06);
            }
        }
    }

